INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m13035$nota-0101$m13035$, $m13036$Training and Racing with a Power Meter.pdf$m13036$, $m13037$276$m13037$, $m13038$The testing on Day 3 on the bike will be tough; he'll test both his 5-minute VO2max power and his 20-minute effort. He'll take 5 percent off his 20-minute average power and use that as his FTP for the rest of the plan. The 5-minute test is critical because it helps to exhaust his FRC$m13038$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m13039$nota-0101$m13039$, $m13040$Training and Racing with a Power Meter.pdf$m13040$, $m13041$277$m13041$, $m13042$and therefore make his 20-minute test (less 5 percent) more accurate as an estimation of FTP. At the same time this is a great measure of his VO2max power, which could be higher than the Coggan Classic levels of 106–120 percent of FTP. If Joe does a great 5-minute test and cranks out 150 percent of his FTP, then he'll want to use the iLevels as the basis for his training.$m13042$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m13043$nota-0101$m13043$, $m13044$nota-0020$m13044$, $m13045$complementa$m13045$, $m13046$refina o protocolo padrão do teste de 20 minutos (menos 5%) já registrado em nota-0020, combinando-o com um teste de 5 minutos no mesmo dia (corrigido em 2026-08-02 — a referência antiga apontava para nota-0021, sobre frequência de reteste de FTP, assunto não relacionado)$m13046$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m13047$nota-0127$m13047$, $m13048$Training and Racing with a Power Meter.pdf$m13048$, $m13049$372$m13049$, $m13050$it is possible to measure your effective frontal area, or CdA (i.e., the product of the dimensionless coefficient of drag, Cd, and frontal area, A, measured in square meters)... three different approaches may be used: the constant speed (or constant power) method, the regression method, or the virtual elevation method.$m13050$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m13051$nota-0127$m13051$, $m13052$Training and Racing with a Power Meter.pdf$m13052$, $m13053$373$m13053$, $m13054$the relationship is well described by a curvilinear equation of the form: Y = aX + bX3, where 'a' is a constant representing the rolling resistance (in newtons, N) and 'b' is proportional to one-half times the air density... times CdA.$m13054$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m13055$nota-0127$m13055$, $m13056$Training and Racing with a Power Meter.pdf$m13056$, $m13057$375$m13057$, $m13058$Dr. Robert Chung developed this approach... the rider simply collects speed and power data while repeatedly riding over the same stretch of road... These data are then used along with the total mass and other factors to solve for the apparent, or virtual, elevation profile.$m13058$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m13059$nota-0127$m13059$, $m13060$Training and Racing with a Power Meter.pdf$m13060$, $m13061$375$m13061$, $m13062$under ideal conditions it is possible to quantify CdA via such field-testing with a coefficient of variation (i.e., reproducibility) of less than 2 percent.$m13062$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m13063$nota-0133$m13063$, $m13064$Training and Racing with a Power Meter.pdf$m13064$, $m13065$384$m13065$, $m13066$Dr. Jim Martin of the University of Utah... has shown that world-class match sprinters tend to initiate their jump during a flying 200-meter time trial essentially right at the cadence that results in maximal power output—beyond this point, power declines continuously because of increases in cadence beyond this optimum as well as fatigue... it is important for such riders to train not only to increase their peak power, but also to be as fatigue-resistant as possible at very high cadences (for example, 140–160 rpm).$m13066$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m13067$nota-0134$m13067$, $m13068$Training and Racing with a Power Meter.pdf$m13068$, $m13069$386$m13069$, $m13070$the results of two 3 km pursuits performed by the same rider are compared. The race at sea level took place on a 333.3-meter concrete track, and the race at altitude took place on a very similar track. The rider went nearly 6 seconds faster at altitude. But when the data are adjusted for the effects of the reduced atmospheric pressure on both aerodynamic drag and aerobic power output, the predicted power—and hence time—are identical to what was achieved at sea level.$m13070$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m13071$nota-0134$m13071$, $m13072$nota-0113$m13072$, $m13073$complementa$m13073$, $m13074$outro exemplo de fator externo (altitude, além do perfil de elevação) que distorce a relação simples entre potência e tempo/velocidade$m13074$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m13075$nota-0144$m13075$, $m13076$Training and Racing with a Power Meter.pdf$m13076$, $m13077$468$m13077$, $m13078$Aliasing Distortion or artifact in data (such as from a power meter) that occurs when an analog signal is sampled at too low of frequency.$m13078$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m13079$nota-0163$m13079$, $m13080$Manual treinamento.pdf$m13080$, $m13081$68$m13081$, $m13082$Sedentários 25–40 | Ativos 40–55 | Ciclistas amadores 50–65 | Elite nacional 65–75 | Elite internacional 75–85 | Valores excepcionais >85 (mL·kg⁻¹·min⁻¹)... esses intervalos representam apenas referências gerais. O desempenho competitivo nunca deve ser previsto exclusivamente a partir do VO₂máx.$m13082$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m13083$nota-0163$m13083$, $m13084$nota-0161$m13084$, $m13085$pre-requisito$m13085$, $m13086$os valores da tabela são expressos em VO2 relativo (mL·kg⁻¹·min⁻¹), conforme definido na nota-0161$m13086$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m13087$nota-0183$m13087$, $m13088$Manual treinamento.pdf$m13088$, $m13089$102$m13089$, $m13090$Ainda não existe um método universal. Entretanto, diferentes abordagens vêm sendo utilizadas: comparação de testes antes e após exercício prolongado; queda da Potência Crítica; alteração dos limiares; redução do VO₂ correspondente a determinadas intensidades; análise da curva potência-duração antes e depois de esforços prolongados.$m13090$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m13091$nota-0183$m13091$, $m13092$nota-0177$m13092$, $m13093$pre-requisito$m13093$, $m13094$um dos métodos propostos usa a queda da Potência Crítica (nota-0177) medida antes/depois de exercício prolongado$m13094$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m13095$nota-0183$m13095$, $m13096$nota-0080$m13096$, $m13097$complementa$m13097$, $m13098$a comparação da curva potência-duração antes/depois de fadiga é conceitualmente equivalente à métrica TTE já operacionalizada na nota-0080 do Livro 1$m13098$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m13099$nota-0206$m13099$, $m13100$VO2 Max Essentials_Final.pdf$m13100$, $m13101$10$m13101$, $m13102$If you own a fitness watch, it likely estimates your VO2 max using one of several different algorithms. I've voiced my opinions on the limitations of wearable-estimated VO2 max before, and I don't think you should put much stock into what your Garmin/WHOOP says about your VO2 max... you can get a very rough estimate of your aerobic fitness, and whether it's trending upward or downward, based on information from these devices.$m13102$);
